-- Full restaurant seed, generated from live DB state. Reproducible source of
-- truth: a fresh DB gets all rows with every column; on an existing DB only the
-- structural columns are refreshed (content columns like name/deals/address are
-- left as-is so manual edits are never clobbered).
ON CONFLICT (id) DO UPDATE SET
  slug = EXCLUDED.slug,
  cuisine_zh_hans = EXCLUDED.cuisine_zh_hans,
  cuisine_zh_hant = EXCLUDED.cuisine_zh_hant,
  last_deals_verified_at = EXCLUDED.last_deals_verified_at,
  is_buffet = EXCLUDED.is_buffet;
